head.script:
scwin.setColumnID = function(obj) {
	var column = {};
	var columnArr = [];
	var gridHeader = "",
		gridBody = "";
	for (var k in obj[0]) {
		column = {};
		column["id"] = k;
		column["dataType"] = "text";
		columnArr.push(column);
		gridHeader += '<w2:column id="' + 'h' + k + '" style="height:20px" inputType="text" width="70" value="' + k + '" useFilter="true"></w2:column>';
		if (k == 'col1') {
			gridBody += '<w2:column id="' + k + '" style="height:20px" inputType="text" width="70" useFilter="true"></w2:column>'
		} else {
			gridBody += '<w2:column id="' + k + '" style="height:20px" inputType="text" width="70" useFilter="true"></w2:column>'
		}
	}
	var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" id="gridView1" style="width: 300px;height: 350px;" fixedColumnWithHidden="true" useShiftKey="false" ev:ongroupby="scwin.ongroupby" groupbyZone="true" groupbyFilterBox="true" customFilterBox="true" useFilterList="true" >' +
		'<w2:header id="header1">' +
		'<w2:row id="row1">' +
		gridHeader +
		'</w2:row>' +
		'</w2:header>' +
		'<w2:gBody id="gBody1">' +
		'<w2:row id="row2">' +
		gridBody +
		'</w2:row>' +
		'</w2:gBody>' +
		'</w2:gridView>';
	gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
	dataList1.setJSON(obj);
};
scwin.ongroupby = function(options) {
	options.groupbyHeader = [];
	options.groupbyFooter = [];
	options.hideFooter = true;
	this.groupby(options);
	return false;
};
scwin.___isCheckLog = function() {
	return WebSquare.logger.getErrorLog() == "";
};
